{"description":"Compare our output with python-chess on sample","cmd":"cd /app && python3 - <<'PY'
import json, re, chess
fen="rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"
s=fen
for pattern, repl in json.load(open('/app/re.json')):
    s = re.sub(pattern, repl, s)
ours=[(' '.join(x.split(' ')[:-2])) for x in s.split('\n')]
board=chess.Board(fen)
ref=set()
for move in board.legal_moves:
    if move.promotion and move.promotion != chess.QUEEN:
        continue
    b=board.copy(); b.push(move)
    ref.add(' '.join(b.fen().split(' ')[:-2]))
print("ours count", len(ours), "ref count", len(ref))
print("Extra (ours not in ref):")
for x in ours:
    if x not in ref and x.rpartition(' ')[0]+' -' not in ref:
        print("  EXTRA:", x)
print("Missing (ref not in ours):")
for x in ref:
    if x not in ours and x.rpartition(' ')[0]+' -' not in ours:
        print("  MISSING:", x)
