{"description":"Find a2-a4 rule and test match","cmd":"cd /app && python3 - <<'PY'
import json, re
rules=json.load(open('/app/re.json'))
# a2-a4: s=48,t=32, intermediate 40. Pattern s>t: ^(?=.{40}\.)(.{32})(\.)(.{15})(P)(.{15})\|([^|]*)\|([^|]*)>(.*)$
search='(?=.{40}\\.)'
for i,(p,r) in enumerate(rules):
    if search in p and '(.{32})(\\.)' in p and '(P)' in p:
        print("rule idx",i)
        print("pattern:",p[:120])
        print("repl:",r[:120])
        break
else:
    print("not found")
# Now test the pattern against the working line
if True:
    # reconstruct
    ws='rnbqkbnrpppp.ppp............p.......P...........PPPP.PPPRNBQKBNR|KQkq|->'
    # find rule by scanning all
    for i,(p,r) in enumerate(rules):
        try:
            if re.match(p, ws):
                print("MATCH rule",i, p[:80])
        except Exception as e:
            pass
